contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address target, address[] memory tos, uint v) public payable {
        require(tos.length > 0);

        bool reverted;
        bool result;
        try c.transfer(from, target, tos, v) returns (bool r) {
            result = r;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted && result) {
            if (target.code.length > 0) {
                bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
                for (uint i = 0; i < tos.length; i++) {
                    (bool ok,) = target.call(abi.encodeWithSelector(id, from, tos[i], v));
                    assert(ok);
                }
            } else {
                assert(true);
            }
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

