        tos[1] = t1;

        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
        (bool ok0,) = caddress.call(abi.encodeWithSelector(id, from, tos[0], uint256(1)));
        (bool ok1,) = caddress.call(abi.encodeWithSelector(id, from, tos[1], uint256(1)));
        bool allPassed = ok0 && ok1;

        bool reverted;
        bool returned;
        try c.transfer(from, caddress, tos, uint256(1)) {
            reverted = false;
            returned = true;
        } catch {
            reverted = true;
            returned = false;
        }

        assert(reverted == !allPassed && returned == allPassed);
    }

    receive() external payable {}
}

